	@Test
	void reservationsAccumulateAndReleaseByKind() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1000);

		assertThat(account.tryReserve(MemoryKind.BASE, 400)).isTrue();
		assertThat(account.tryReserve(MemoryKind.DELTA, 300)).isTrue();
		assertThat(account.chargedBytes(MemoryKind.BASE)).isEqualTo(400);
		assertThat(account.chargedBytes(MemoryKind.DELTA)).isEqualTo(300);
		assertThat(account.totalChargedBytes()).isEqualTo(700);

		account.release(MemoryKind.DELTA, 300);
		assertThat(account.chargedBytes(MemoryKind.DELTA)).isZero();
		assertThat(account.totalChargedBytes()).isEqualTo(400);
	}

	@Test
	void reservationBeyondLimitIsRefusedAndRecorded() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1000);

		assertThat(account.tryReserve(MemoryKind.BASE, 900)).isTrue();
		assertThat(account.tryReserve(MemoryKind.BUILD_OUTPUT, 200)).isFalse();
		assertThat(account.chargedBytes(MemoryKind.BUILD_OUTPUT)).isZero();
		assertThat(account.totalChargedBytes()).isEqualTo(900);
		assertThat(account.refusedBytes()).isEqualTo(200);
		assertThat(account.refusedCount()).isEqualTo(1);

		// an exact fit is still accepted
		assertThat(account.tryReserve(MemoryKind.BUILD_OUTPUT, 100)).isTrue();
		assertThat(account.totalChargedBytes()).isEqualTo(1000);
	}

